function Stat({title,value,subtitle,icon,danger,currency}:Any){return <article className="stat"><div><span>{title}</span><span className={danger?'statIcon danger':'statIcon'}>{icon}</span></div><h2><small>{currency}</small> {money(value,currency)}</h2><p className={danger&&value?'red':''}>{subtitle}</p></article>}
